// 故意出错的件：cordis 住主进程时，件的错落在主进程上。三种形态各一条条目。
export const name = 'gwb-probe-faulty'

export function apply(ctx, config = {}) {
  const mode = config.mode ?? 'none'
  ctx.logger('probe-faulty').info(`apply, mode=${mode}`)
  if (mode === 'throw-apply') throw new Error('sync throw in apply')
  if (mode === 'reject-later') setTimeout(() => void Promise.reject(new Error('unhandled rejection from timer')), 100)
  if (mode === 'throw-later') setTimeout(() => { throw new Error('sync throw in timer') }, 200)
}
